package com.citacloud.app.services; import com.citacloud.app.models.AuditoriaEvento; import com.citacloud.app.repositories.AuditoriaEventoRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class AuditoriaService {private final AuditoriaEventoRepository repo;public AuditoriaService(AuditoriaEventoRepository r){repo=r;}public void registrar(UUID empresa,UUID usuario,String modulo,String accion,String entidad,UUID registro,String datos){AuditoriaEvento e=new AuditoriaEvento();e.setEmpresaId(empresa);e.setUsuarioId(usuario);e.setModulo(modulo);e.setAccion(accion);e.setEntidad(entidad);e.setRegistroId(registro);e.setDatosNuevos(datos);repo.save(e);}public List<AuditoriaEvento> listar(UUID empresa){return repo.findByEmpresaIdOrderByFechaDesc(empresa);}}
